import{_ as o,l as i,o as e,c as l,v as t,p as n,x as s,d as F,i as S,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"FCFS 与 SJF","description":"","frontmatter":{"title":"FCFS 与 SJF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fcfs-sjf.md","filePath":"cs/fcfs-sjf.md","lastUpdated":1789023840000}'),d={name:"cs/fcfs-sjf.md"};function p(f,a,h,_,m,u){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="fcfs-与-sjf" tabindex="-1">FCFS 与 SJF <a class="header-anchor" href="#fcfs-与-sjf" aria-label="Permalink to &quot;FCFS 与 SJF&quot;">​</a></h1><div class="epigraph"><p>先来先服务实现最直；短作业优先降低平均等待，但要知道或估计下一次 CPU 突发有多长。</p><footer>—— 据 Silberschatz et al., Operating System Concepts 整理</footer></div><p><a href="/cs/runqueue">上一课</a>给出可运行容器。<a href="/cs/scheduling-metrics">调度指标</a>已警告：换尺子，名次就换。缺口是两条经典<strong>非抢占</strong>（SJF 可做成抢占的 SRTF）策略：FCFS 按入队序；SJF 按下一次突发最短者先跑。本课对着同一组到达与突发比较，不引入时间片。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FCFS：runqueue 当 FIFO，实现即入队出队。长 CPU 型先到，后面一串 I/O 型的等待被拖长，即传送带效应。SJF：选估计突发最短的，平均等待往往更优；证明「非抢占 SJF 平均等待最优」教材可引，本课只锁定直觉与代价——<strong>长度未知</strong>。缺口不是新的队列结构，而是用指标解释这两种取队头的规则。</p><p><span class="marginnote">抢占式最短剩余时间（SRTF）在新短作业到达时打断当前长作业，响应更好，切换更多。估计常用指数平均：最近突发与历史的凸组合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定到达时间与突发，画出甘特图，算平均等待与周转。FCFS 不需要估计。SJF 需要预言或估计；估计偏长则退化成近 FCFS，偏短则可能饿死长作业——饥饿是公平尺子，不是平均等待。本课点名饥饿，不把多级反馈请进来。</p>',8)),(e(),n(c,null,{default:s(()=>[S(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARR%5B%22%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20FCFS%5B%22FCFS%3A%20%E5%85%A5%E9%98%9F%E5%BA%8F%22%5D%0A%20%20ARR%20--%3E%20SJF%5B%22SJF%3A%20%E6%9C%80%E7%9F%AD%E7%AA%81%E5%8F%91%E5%85%88%22%5D%0A%20%20FCFS%20--%3E%20M%5B%22%E7%AD%89%E5%BE%85%E4%B8%8E%E5%91%A8%E8%BD%AC%22%5D%0A%20%20SJF%20--%3E%20M%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[F(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>两者默认跑到突发结束（阻塞或结束）才再选，除非用 SRTF。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>FCFS 对 I/O 型不友好当它排在长计算后面；SJF 照顾 I/O 型（短突发）从而抬利用率。交互响应仍可能差：一个中等突发也能挡住击键，因为没有时间片上限。这把下一课轮转的动机钉在「即使长度未知，也要定期让出」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把实时截止当成短作业。也不把 SJF 说成 Linux 默认。估计误差与恶意谎报长度（用户说自己很短）在开放系统里存在；内核若用实测突发，谎报无效。</p><p>后课默认：非抢占策略平均等待可以很好，响应仍可很差。定期抢占的时间片轮转，下一课收。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FCFS 简单，有传送带效应；SJF 降平均等待，依赖估计，可饿死长作业。</li><li>两者都不自动给出交互响应上限。</li><li>时间片轮转是下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',8))])}const A=o(d,[["render",p]]);export{C as __pageData,A as default};
